        let quotes: [(String, Bool)] = [
            ("The note says \"Can I change Label Tag?\". Can it?", true),
            ("The note says “Can I change Label Tag?”. Can it?", true),
            ("The note says 'Can I change Label Tag?'. Can it?", true),
